<script setup>import AdminShell from '../../components/AdminShell.vue';import StatusBadge from '../../components/StatusBadge.vue';import {workOrders} from '../../api/mock';</script>
<template><AdminShell><template #title>节能任务</template><div class="heading"><div><p>MAINTENANCE EXECUTION</p><h1>节能任务中心</h1><span>从异常报修、派工执行到验收归档的全过程闭环</span></div><button class="btn primary">＋ 创建节能任务</button></div>
 <section class="work-flow"><div><small>01</small><span>待接单</span><b>8</b><i>→</i></div><div><small>02</small><span>处理中</span><b>17</b><i>→</i></div><div><small>03</small><span>待验收</span><b>12</b><i>→</i></div><div><small>04</small><span>今日完成</span><b>26</b></div><aside><span>平均修复时长 MTTR</span><b>3.6 h</b><small>较上月缩短 0.4 h</small></aside></section>
 <section class="panel"><div class="toolbar"><div class="tabs"><button class="active">全部工单 <b>37</b></button><button>我的待办 <b>6</b></button><button>超时风险 <b>3</b></button><button>待验收 <b>12</b></button></div><div><label>⌕ <input placeholder="搜索工单或计量设备"/></label><button>筛选 ⌄</button></div></div><table class="change-table"><thead><tr><th>工单号 / 节能事项</th><th>关联资产</th><th>工单类型</th><th>优先级</th><th>负责人</th><th>承诺完成</th><th>状态</th><th></th></tr></thead><tbody><tr v-for="(w,i) in workOrders" :key="w.no"><td><b>{{w.no}}</b><small>{{w.title}}</small></td><td><span class="model-chip">{{w.asset}}</span></td><td>{{w.type}}</td><td><StatusBadge :value="w.priority"/></td><td><span class="avatar">{{w.assignee[0]}}</span>{{w.assignee}}</td><td :class="i===0?'overdue':''">{{w.due}}<small v-if="i===0">剩余 3 小时</small></td><td><StatusBadge :value="w.status"/></td><td>•••</td></tr></tbody></table><div class="table-note"><span>显示 1–4，共 37 条记录</span><div><button>‹</button><button class="active">1</button><button>2</button><button>3</button><button>›</button></div></div></section>
 <div class="grid work-bottom"><section class="panel"><header><div><h2>班组负荷</h2><p>今日剩余可用工时</p></div><em>自动均衡建议</em></header><div class="team-load"><div><span><b>精密节能组</b><small>6 人 · 14 项任务</small></span><i><em style="width:84%"></em></i><strong>84%</strong></div><div><span><b>公用工程组</b><small>5 人 · 9 项任务</small></span><i><em style="width:62%"></em></i><strong>62%</strong></div><div><span><b>物流计量设备组</b><small>4 人 · 8 项任务</small></span><i><em style="width:76%"></em></i><strong>76%</strong></div></div></section><section class="panel"><header><div><h2>异常原因分布</h2><p>本月已关闭节能任务</p></div><button>查看可靠性分析 →</button></header><div class="cause-list"><span><i style="width:74%"></i><b>机械磨损</b><em>31%</em></span><span><i style="width:53%"></i><b>电气异常</b><em>24%</em></span><span><i style="width:39%"></i><b>参数漂移</b><em>18%</em></span><span><i style="width:22%"></i><b>操作因素</b><em>11%</em></span></div></section></div>
 </AdminShell></template>
